#[path="../src/semantic.rs"] mod semantic;
use semantic::SemanticService;use rusqlite::Connection;use std::{thread,time::{Duration,Instant}};
fn ready(s:&SemanticService,p:&std::path::Path){let end=Instant::now()+Duration::from_secs(60);while Instant::now()<end{if s.status(p)["available"]==true{return}thread::sleep(Duration::from_millis(30));}panic!("not ready: {}",s.status(p))}
#[test]fn successful_rebuilds_keep_only_live_generations(){let p=std::env::temp_dir().join(format!("atlas-gen-clean-{}",std::process::id()));atlas_native_storage_contract::create_workspace(&p).unwrap();let c=Connection::open(p.join("atlas.sqlite3")).unwrap();let s=SemanticService::start("/private/tmp/atlas-llama-bin/llama-b12001/llama-server","/private/tmp/atlas-embeddinggemma-bf16.gguf").unwrap();for i in 0..3{let id=format!("note{i}");c.execute("INSERT INTO objects(id,kind,title,path,description,text_status) VALUES (?,'note',?,'','', 'available')",[&id,&id]).unwrap();c.execute("INSERT INTO search_index(object_id,title,body) VALUES (?,?,?)",[&id,&id,"текст"]).unwrap();s.enqueue(&p,None).unwrap();ready(&s,&p);}let dir=p.join(".atlas-semantic-native");let current=std::fs::read_to_string(dir.join("current")).unwrap();let current=current.trim();let base=atlas_joined_probe::overlay_gen::base_generation(&dir,current).unwrap();let mut expected=std::collections::BTreeSet::from([current.to_owned()]);if let Some(base)=base{expected.insert(base);}let actual:std::collections::BTreeSet<String>=std::fs::read_dir(&dir).unwrap().filter_map(Result::ok).filter_map(|entry|entry.file_name().into_string().ok()).filter(|name|name.starts_with("gen-")).collect();assert_eq!(actual,expected,"unexpected old generations remain");let results=s.search(&p,"текст",None).unwrap();for id in ["note0","note1","note2"]{assert!(results.iter().any(|row|row["id"]==id),"missing searchable source {id}");}drop(c);s.close(&p).unwrap();std::fs::remove_dir_all(p).unwrap();}
#[test]fn failed_rebuild_keeps_current(){let p=std::env::temp_dir().join(format!("atlas-gen-fail-{}",std::process::id()));atlas_native_storage_contract::create_workspace(&p).unwrap();let c=Connection::open(p.join("atlas.sqlite3")).unwrap();c.execute_batch("INSERT INTO objects(id,kind,title,path,description,text_status) VALUES ('a','note','test','','','available');INSERT INTO search_index(object_id,title,body) VALUES ('a','test','текст');").unwrap();let s=SemanticService::start("/private/tmp/atlas-llama-bin/llama-b12001/llama-server","/private/tmp/atlas-embeddinggemma-bf16.gguf").unwrap();s.enqueue(&p,None).unwrap();ready(&s,&p);let dir=p.join(".atlas-semantic-native");let current=std::fs::read_to_string(dir.join("current")).unwrap();c.execute("DROP TABLE search_index",[]).unwrap();s.enqueue(&p,None).unwrap();let end=Instant::now()+Duration::from_secs(30);while Instant::now()<end {if s.status(&p)["message"].as_str().unwrap_or("").contains("no such table") {break}thread::sleep(Duration::from_millis(30));}assert!(!s.status(&p)["available"].as_bool().unwrap());assert!(s.status(&p)["message"].as_str().unwrap().contains("no such table"));assert_eq!(std::fs::read_to_string(dir.join("current")).unwrap(),current);assert!(dir.join(current.trim()).join("index.faiss").is_file());assert!(dir.join(current.trim()).join("metadata.json").is_file());drop(c);s.close(&p).unwrap();std::fs::remove_dir_all(p).unwrap();}
#[cfg(feature="test-hook")]
#[test]fn publication_waits_for_active_model_read(){let p=std::env::temp_dir().join(format!("atlas-gen-race-{}",std::process::id()));atlas_native_storage_contract::create_workspace(&p).unwrap();let c=Connection::open(p.join("atlas.sqlite3")).unwrap();c.execute_batch("INSERT INTO objects(id,kind,title,path,description,text_status) VALUES ('a','note','test','','','available');INSERT INTO search_index(object_id,title,body) VALUES ('a','test','старый текст');").unwrap();let s=SemanticService::start("/private/tmp/atlas-llama-bin/llama-b12001/llama-server","/private/tmp/atlas-embeddinggemma-bf16.gguf").unwrap();s.enqueue(&p,None).unwrap();ready(&s,&p);let d=p.join(".atlas-semantic-native");let before=std::fs::read_to_string(d.join("current")).unwrap();let (ready_tx,ready_rx)=std::sync::mpsc::channel();let (resume_tx,resume_rx)=std::sync::mpsc::channel();let clone=s.clone();let holder=thread::spawn(move||clone.with_model_lock_for_test(ready_tx,resume_rx));ready_rx.recv_timeout(Duration::from_secs(5)).unwrap();c.execute("UPDATE search_index SET body='новый текст' WHERE object_id='a'",[]).unwrap();s.enqueue(&p,Some("a")).unwrap();thread::sleep(Duration::from_millis(300));assert_eq!(std::fs::read_to_string(d.join("current")).unwrap(),before);assert!(d.join(before.trim()).join("index.faiss").exists());resume_tx.send(()).unwrap();holder.join().unwrap();ready(&s,&p);let current=std::fs::read_to_string(d.join("current")).unwrap();assert_ne!(before,current);assert!(d.join(current.trim()).join("index.faiss").exists());s.close(&p).unwrap();drop(c);std::fs::remove_dir_all(p).unwrap();}
